function runSmoke() {
  const cases = [
    {
      name: 'saludo_no_flow',
      message: 'Hola',
      attrs: { tac_notice_sent: true },
      expected: { route: 'agent_default', shouldSendPersonalFlow: false },
    },
    {
      name: 'saludo_inicial_envia_flow_sin_agente',
      message: 'Hola',
      attrs: { tac_notice_sent: false, is_whatsapp: true },
      expected: { workflowRoute: 'initial_personal_flow_only', shouldReachAgentAfterInitialFlow: false },
    },
    {
      name: 'tac_true_sin_welcome_flow_pendiente_envia_flow',
      message: 'Hola',
      attrs: { tac_notice_sent: true, welcome_personal_flow_sent: false, is_whatsapp: true },
      expected: { workflowRoute: 'initial_personal_flow_only', shouldReachAgentAfterInitialFlow: false },
    },
    {
      name: 'producto_precio_no_flow',
      message: 'Cuanto cuesta el Tucson manual',
      attrs: { tac_notice_sent: true },
      expected: { route: 'agent_default', shouldSendPersonalFlow: false },
    },
    {
      name: 'repuestos_no_flow',
      message: 'Necesito repuestos para Hyundai Sonata',
      attrs: { tac_notice_sent: true },
      expected: { route: 'agent_default', shouldSendPersonalFlow: false },
    },
    {
      name: 'agenda_sin_modelo_no_flow',
      message: 'Quiero agendar una prueba de manejo',
      attrs: { tac_notice_sent: true },
      expected: { route: 'agent_default', shouldSendPersonalFlow: false },
    },
    {
      name: 'agenda_con_modelo_envia_flow',
      message: 'Quiero agendar una prueba de manejo del Tucson',
      attrs: { tac_notice_sent: true },
      expected: { route: 'send_personal_flow', shouldSendPersonalFlow: true },
    },
    {
      name: 'si_despues_de_oferta_test_drive_envia_flow',
      message: 'Si',
      attrs: { tac_notice_sent: true, booking_last_agent_offer: 'test_drive_offer', selected_model: 'TUCSON' },
      expected: { route: 'send_personal_flow', shouldSendPersonalFlow: true },
    },
    {
      name: 'flow_repetido_bloqueado',
      message: 'Quiero agendar una prueba de manejo del Tucson',
      attrs: { tac_notice_sent: true, selected_model: 'TUCSON', welcome_personal_flow_sent: true },
      expected: { route: 'agent_default', shouldSendPersonalFlow: false },
    },
    {
      name: 'mas_info_con_datos_completos_no_reenvia_flow',
      message: 'button_action: mas_info\nmodel: creta_tm\nbutton_text: Mas Info\nbutton_payload: creta_tm__mas_info',
      attrs: {
        tac_notice_sent: true,
        booking_personal_data_complete: true,
        customer_name: 'Cristobal Caceres',
        customer_email: 'cristobalcaceres@hotmail.com',
        customer_identifier: '1720005550',
        customer_phone: '+593984040157',
        selected_city: 'Quito',
        is_whatsapp: true,
      },
      expected: {
        route: 'agent_default',
        workflowRoute: 'normal_agent_path',
        shouldSendPersonalFlow: false,
      },
    },
    {
      name: 'payload_flow_persiste_personal',
      message: 'name: Ana Vera\nidentifier: 0910765478\nemail: ana@example.com\ncity: guayaquil\nflow_token: flow-data-593999999999',
      attrs: {},
      expected: { route: 'flow_payload', personalComplete: true },
    },
    {
      name: 'phase6_sin_concesionario_bloqueado',
      message: 'Quiero agendar una prueba de manejo del Tucson',
      attrs: { customer_name: 'Ana', customer_email: 'ana@example.com', customer_identifier: '0910765478', customer_phone: '+593999999999', selected_city: 'Guayaquil', selected_model: 'TUCSON', selected_date: '2026-07-20', selected_time: '10:00', purchase_timeframe_days: 30 },
      expected: { route: 'agent_default', shouldSendPersonalFlow: false, shouldSendPhase6Flow: false },
    },
    {
      name: 'phase6_con_modelo_concesionario_ok',
      message: 'Quiero cerrar la cita',
      attrs: { booking_intent: 'schedule_phase4', customer_name: 'Ana', customer_email: 'ana@example.com', customer_identifier: '0910765478', customer_phone: '+593999999999', selected_city: 'Guayaquil', selected_model: 'TUCSON', selected_establishment_id: 12, selected_date: '2026-07-20', selected_time: '10:00', purchase_timeframe_days: 30 },
      expected: { route: 'send_phase6_flow', shouldSendPersonalFlow: false, shouldSendPhase6Flow: true },
    },
  ];

  const results = cases.map((item) => {
    const actual = evaluateCase(item.message, item.attrs);
    const assertions = Object.entries(item.expected).map(([key, expected]) => ({
      key,
      expected,
      actual: actual[key],
      ok: actual[key] === expected,
    }));
    return {
      name: item.name,
      ok: assertions.every((assertion) => assertion.ok),
      assertions,
      actual,
    };
  });

  return {
    ok: results.every((item) => item.ok),
    passed: results.filter((item) => item.ok).length,
    failed: results.filter((item) => !item.ok).length,
    total: results.length,
    results,
  };
}

function evaluateCase(message, attrs) {
  const normalized = String(message || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  const flow = parseFlowPayload(message);
  const selectedModel = attrs.selected_model || extractModel(message);
  const selectedModelId = attrs.selected_model_id || null;
  const hasSelectedModelForPersonalFlow = Boolean(selectedModel || selectedModelId);
  const hasPersonalContactData = Boolean(attrs.customer_name && attrs.customer_email && attrs.customer_identifier && attrs.customer_phone);
  const personalComplete = Boolean((hasPersonalContactData && attrs.selected_city) || (flow.name && flow.email && flow.identifier && flow.city) || attrs.booking_personal_data_complete === true);
  const welcomePersonalFlowSent = Boolean(attrs.welcome_personal_flow_sent);
  const personalFlowAlreadySent = welcomePersonalFlowSent || ['personal_data', 'personal_data_early'].includes(String(attrs.booking_flow_sent_type || ''));

  const scheduleKeywords = /(agendar|agenda|agendemos|cita|reservar|reserva|programar|coordinar|test drive|prueba de manejo)/i;
  const hardPhase6Keywords = /(fecha|hora|horario|manana|mañana|tarde|viernes|lunes|martes|miercoles|miércoles|jueves|sabado|sábado|domingo|hoy|\b\d{1,2}:\d{2}\b|\b\d{1,2}\s?(am|pm)\b)/i;
  const productKeywords = /(precio|cuanto|cotiza|cotizacion|informacion|modelo|tucson|creta|accent|kona|grand|i10|repuesto|repuestos)/i;
  const affirmativeShortReply = /^(si|sí|ok|okay|claro|dale|perfecto|me interesa|quiero|correcto)$/i.test(String(message || '').trim());
  const currentStrongSchedule = ['schedule_phase4', 'schedule_phase6'].includes(String(attrs.booking_intent || ''));
  const currentDealershipStage = ['collect_establishment', 'establishment_resolved'].includes(String(attrs.booking_phase || ''));

  let intent = 'fallback';
  if (flow.is_flow_payload) intent = 'flow_payload';
  else if (scheduleKeywords.test(normalized) || hardPhase6Keywords.test(normalized) || (affirmativeShortReply && attrs.booking_last_agent_offer === 'test_drive_offer')) intent = 'schedule_phase4';
  else if (productKeywords.test(normalized)) intent = 'product_info';

  const hasStrongPersonalFlowIntent = ['schedule_phase4', 'schedule_phase6'].includes(intent)
    && (
      scheduleKeywords.test(normalized)
      || hardPhase6Keywords.test(normalized)
      || (affirmativeShortReply && (currentStrongSchedule || attrs.booking_last_agent_offer === 'test_drive_offer' || currentDealershipStage))
    );

  const shouldSendEarlyPersonalFlow = Boolean(
    attrs.tac_notice_sent
    && hasStrongPersonalFlowIntent
    && hasSelectedModelForPersonalFlow
    && !hasPersonalContactData
    && !welcomePersonalFlowSent
    && !personalFlowAlreadySent
    && !flow.is_flow_payload
  );
  const shouldSendPersonalFlow = Boolean(
    ['schedule_phase4', 'schedule_phase6'].includes(intent)
    && hasSelectedModelForPersonalFlow
    && !hasPersonalContactData
    && !flow.is_flow_payload
    && !personalFlowAlreadySent
  );
  const shouldSendPhase6Flow = Boolean(
    personalComplete
    && (selectedModel || selectedModelId)
    && (attrs.selected_establishment_name || attrs.selected_establishment_id)
    && ['schedule_phase4', 'schedule_phase6'].includes(intent)
  );

  let route = 'agent_default';
  if (flow.is_flow_payload) route = 'flow_payload';
  else if (shouldSendEarlyPersonalFlow || shouldSendPersonalFlow) route = 'send_personal_flow';
  else if (shouldSendPhase6Flow) route = 'send_phase6_flow';

  return {
    route,
    workflowRoute: evaluateInitialTacPath(message, attrs).workflowRoute,
    shouldReachAgentAfterInitialFlow: evaluateInitialTacPath(message, attrs).shouldReachAgentAfterInitialFlow,
    intent,
    selectedModel: selectedModel || null,
    shouldSendPersonalFlow: shouldSendEarlyPersonalFlow || shouldSendPersonalFlow,
    shouldSendPhase6Flow,
    personalComplete,
  };
}

function evaluateInitialTacPath(message, attrs) {
  const isWhatsapp = attrs.is_whatsapp === true;
  const isVisa = /si tengo visa americana|no tengo visa americana/i.test(String(message || '').normalize('NFD').replace(/[\u0300-\u036f]/g, ''));
  const flowType = String(attrs.booking_flow_sent_type || '');
  const welcomeFlowSent = Boolean(attrs.welcome_personal_flow_sent || ['personal_data', 'personal_data_early'].includes(flowType));
  const hasPersonalData = Boolean(
    attrs.booking_personal_data_complete
    || (attrs.customer_name && attrs.customer_email && attrs.customer_identifier && attrs.customer_phone)
  );
  const tacHandled = Boolean(attrs.tac_notice_sent && (welcomeFlowSent || hasPersonalData));

  if (!tacHandled && isWhatsapp && !isVisa) {
    return {
      workflowRoute: 'initial_personal_flow_only',
      shouldReachAgentAfterInitialFlow: false,
    };
  }

  return {
    workflowRoute: 'normal_agent_path',
    shouldReachAgentAfterInitialFlow: true,
  };
}

function extractModel(message) {
  const normalized = String(message || '').toLowerCase();
  if (/tucson/.test(normalized)) return 'TUCSON';
  if (/creta/.test(normalized)) return 'CRETA';
  if (/accent/.test(normalized)) return 'ACCENT';
  if (/kona/.test(normalized)) return 'KONA';
  if (/grand\s*i10|\bi10\b/.test(normalized)) return 'GRAND I10';
  return '';
}

function parseFlowPayload(message) {
  const parsed = {};
  for (const line of String(message || '').split(/\r?\n/)) {
    const match = line.trim().match(/^([a-zA-Z0-9_ ]+):\s*(.+)$/);
    if (!match) continue;
    parsed[match[1].trim().toLowerCase().replace(/\s+/g, '_')] = match[2].trim();
  }
  return {
    is_flow_payload: Boolean(parsed.flow_token || ((parsed.name || parsed.email || parsed.identifier || parsed.city) && Object.keys(parsed).length >= 3)),
    name: parsed.name || '',
    identifier: parsed.identifier || '',
    email: parsed.email || '',
    city: parsed.city || '',
  };
}

return [{ json: runSmoke() }];
